function makeHistory(seed: { slug: string; stars: number; g30: number; g90: number; createdAt: string }): { date: string; stars: number }[] {
  // Deterministic weekly series over 90 days ending at AS_OF.
  const points: { date: string; stars: number }[] = [];
  const total = 13; // 13 weekly points ≈ 91 days
  const a = 0.55;
  const b = 0.35;
  // linear + convex growth shape
  for (let i = 0; i < total; i++) {
    const t = (total - 1 - i) / (total - 1); // 0 at oldest, 1 at newest
    const frac = a * t + b * t * t + (1 - a - b) * t * t * t;
    const stars = Math.max(1, Math.round(seed.stars - seed.g90 * (1 - frac)));
    const d = new Date(AS_OF);
    d.setDate(d.getDate() - (total - 1 - i) * 7);
    points.push({ date: d.toISOString().slice(0, 10), stars });
  }
  // ensure final point == stars
  points[points.length - 1] = { date: AS_OF, stars: seed.stars };
  return points;
}

function toProject(s: Seed): Project {
  return {
    id: s.slug,
    slug: s.slug,
    name: s.name,
    owner: s.owner,
    fullName: `${s.owner}/${s.name}`,
    tagline: s.tagline,
    description: s.description,
    homepage: s.homepage,
    language: s.language,
    license: s.license,
    stars: s.stars,
    forks: s.forks,
    contributors: s.contributors,
    openIssues: s.openIssues,
    releases: s.releases,
    createdAt: s.createdAt,
    updatedAt: s.updatedAt,
    categories: s.categories,
    topics: s.topics,
    growth7d: s.g7,
    growth30d: s.g30,
    growth90d: s.g90,
    profile: s.profile,
    growthHistory: makeHistory(s),
  };
}

export const SEED_PROJECTS: Project[] = S.map(toProject);

export const PROJECTS: Project[] = SEED_PROJECTS;

export function getProject(slug: string): Project | undefined {
  return PROJECTS.find((p) => p.slug === slug);
}
